import type { ResponseInputItem, ResponseOutputItem } from 'openai/resources/responses/responses';
import { GetCaseContextResultSchema, GetOrderShipmentsResultSchema, FindCasesResultSchema } from '../src/ai/tools';
import type { AgentSuggestion, DbRows } from '@seapilot/contracts';
import type { ResponsesClient } from '../src/ai/agent';

export const M1 = 'I ordered a T-shirt and a cap but only got the T-shirt. Here is a photo of the parcel, please check.';
export const M2 = 'The missing cap from yesterday is still not solved. I already sent a photo, do I have to explain everything again?';
export const M3 = 'I got the second parcel, but there was no cap inside. Here is a photo of the second parcel.';

// Exercises the real agent tool loop; suggestions derive from tool output, not hidden store access.
export function mockModel(): ResponsesClient {
  return { responses: { async create(body) {
    const input = body.input as ResponseInputItem[];
    const first = input[0] as { content: string };
    const context = JSON.parse(first.content) as { customer_id: string; order_id: string; messages: DbRows['messages'][]; evidence: DbRows['evidence'][] };
    const output = (id: string) => input.find(item => item.type === 'function_call_output' && item.call_id === id);
    const result = (id: string): unknown => {
      const item = output(id);
      return item?.type === 'function_call_output' && typeof item.output === 'string' ? JSON.parse(item.output) : undefined;
    };
    const call = (name: string, args: unknown): ResponseOutputItem => ({ type: 'function_call', id: `fc-${name}`, call_id: name, name, arguments: JSON.stringify(args), status: 'completed' });
    const tools = (...output: ResponseOutputItem[]) => ({ status: 'completed' as const, output, output_text: '' });
    if (!output('find_cases')) return tools(call('find_cases', { customer_id: context.customer_id, order_id: context.order_id }), call('get_order_shipments', { order_id: context.order_id }));
    const candidates = FindCasesResultSchema.parse(result('find_cases'));
    const shipments = GetOrderShipmentsResultSchema.parse(result('get_order_shipments'));
    const candidate = candidates[0];
    if (candidate && !output('get_case_context')) return tools(call('get_case_context', { case_id: candidate.case_id }));
    const history = candidate ? GetCaseContextResultSchema.parse(result('get_case_context')) : null;
    const evidence = history?.evidence ?? context.evidence;
    const receivedEmpty = context.messages.some(message => message.role === 'customer' && message.text === M3);
    const hasEarlierPhoto = evidence.some(item => item.path.endsWith('parcel_a.jpg'));
    const secondDelivered = shipments.parcels.find(item => item.parcel_code === 'B')?.status === 'delivered';
    const suggestion: AgentSuggestion = {
      suggested_case_id: candidate?.case_id ?? null, link_confidence: candidate?.score ?? 0, link_reason: candidate?.reason ?? 'No existing case.',
      known_facts: [{ text: `Parcel B: ${secondDelivered ? 'delivered' : 'in transit'}.`, source: 'system' }, ...evidence.map(item => ({ text: `Photo retained: ${item.id}`, source: item.source }))],
      changes: history?.changes_since_last_contact.map(item => ({ text: `Parcel ${item.parcel_code} changed.`, before: item.before, after: item.after })) ?? [],
      missing_info: candidate && !receivedEmpty ? ['Was parcel B received without the cap?'] : [],
      draft_reply: receivedEmpty ? 'We have recorded the empty second parcel and both photos. We have escalated the evidence to Warehouse Ops. You do not need to send the photos again.'
        : candidate ? `${hasEarlierPhoto ? 'We have your earlier parcel A photo; you do not need to resend it.' : 'Please send the parcel A photo again.'} The system now marks parcel B delivered. Did it arrive without the cap?`
        : 'Order DH001 is split: the T-shirt parcel was delivered and the cap parcel is still in transit. We have recorded your photo and will follow up.',
      proposed_action: receivedEmpty ? { type: 'escalate_to_ops', reason: 'Customer reports parcel B arrived empty.', evidence_ids: evidence.map(item => item.id) } : null,
    };
    return { status: 'completed', output: [], output_text: JSON.stringify(suggestion) };
  } } };
}
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { DbRowSchemas, type DbTable } from '@seapilot/contracts';
import { connectDatabase } from '../db/client';
import { createPostgresStore } from './postgres';
import { createDemoService } from '../demo/service';
import { buildSeed } from '../demo/seed';
import { createApp } from '../app';
import { find_cases } from '../ai/tools';

// Deliberately do not load .env: integration tests truncate the explicitly selected DB.
const url = process.env.DATABASE_URL;
if (!url) console.warn('SKIP PostgreSQL integration tests: DATABASE_URL is unset. Start Docker, migrate, then run tests with DATABASE_URL set.');
describe.skipIf(!url)('PostgreSQL integration (real database; resets all demo tables)', () => {
  let connection: ReturnType<typeof connectDatabase>;
  let store: ReturnType<typeof createPostgresStore>;
  let demo: ReturnType<typeof createDemoService>;
  beforeAll(async () => {
    connection = connectDatabase(url!);
    store = createPostgresStore(connection.db);
    demo = createDemoService(store);
    expect(await store.health(), 'DATABASE_URL must point to a running migrated PostgreSQL database').toBe(true);
  });
  beforeEach(async () => { await demo.reset(); });
  afterAll(async () => { if (connection) await connection.close(); });
  const snapshot = async () => Object.fromEntries(await Promise.all((Object.keys(DbRowSchemas) as DbTable[]).map(async table => [table, await store.list(table)])));
  const withoutTimes = (value: unknown) => JSON.parse(JSON.stringify(value, (key, val) => key.endsWith('_at') ? undefined : val));
  it('reset twice yields identical business rows across all ten tables', async () => {
    const first = await snapshot();
    await demo.advanceDay();
    await demo.reset();
    expect(withoutTimes(await snapshot())).toEqual(withoutTimes(first));
    expect(await store.list('customers')).toHaveLength(3);
    expect(await store.list('orders')).toHaveLength(3);
    expect(await store.list('cases')).toEqual([]);
  });
  it('jump demo2 creates exactly CS001, CONV1, EV1 and four events', async () => {
    const app = createApp(store, { token: [REDACTED], demo });
    const response = await app.request('/api/demo/jump?to=demo2', { method: 'POST', headers: { 'x-demo-token': [REDACTED] } });
    expect(response.status).toBe(200);
    expect((await store.list('cases')).map(row => row.id)).toEqual(['CS001']);
    expect((await store.list('conversations')).map(row => row.id)).toEqual(['CONV1']);
    expect((await store.list('evidence')).map(row => row.id)).toEqual(['EV1']);
    expect(await store.list('case_events')).toHaveLength(4);
    expect((await store.get('case_events', 'CE4'))?.payload.shipment_snapshot).toEqual({ A: 'delivered', B: 'in_transit' });
  });
  it('advance updates B at the old clock time, audits every unresolved DH001 case, then advances', async () => {
    await demo.reset('After Demo 1');
    const existing = (await store.get('cases', 'CS001'))!;
    await store.createCase({ ...existing, id: 'CS002', status: 'waiting_customer' });
    await store.createCase({ ...existing, id: 'CS003', status: 'resolved' });
    await store.createCase({ ...existing, id: 'CS004', order_id: 'DH002' });
    const before = demo.clock.now().toISOString();
    const app = createApp(store, { token: [REDACTED], demo });
    expect((await app.request('/api/demo/advance-day', { method: 'POST', headers: { 'x-demo-token': [REDACTED] } })).status).toBe(200);
    expect((await store.list('shipments', { order_id: 'DH001', parcel_code: 'B' }))[0]).toMatchObject({ status: 'delivered', updated_at: before });
    const events = await store.list('case_events', { type: 'shipment_updated' });
    expect(events.map(row => row.case_id).sort()).toEqual(['CS001', 'CS002']);
    expect(events.every(row => row.created_at === before)).toBe(true);
    expect(demo.clock.now().getTime()).toBe(Date.parse(before) + 86_400_000);
  });
  it('rolls back truncate and inserts when a seed violates a foreign key', async () => {
    await demo.reset('After Demo 1');
    const before = await snapshot();
    const invalid = buildSeed('Start', demo.clock);
    invalid.orders[0].customer_id = 'MISSING';
    await expect(store.resetTo(invalid)).rejects.toThrow();
    expect(await snapshot()).toEqual(before);
  });
  it('links pending evidence, hands over ownership and records both events', async () => {
    await demo.reset('After Demo 1');
    const at = demo.clock.now().toISOString();
    const conversation = await store.createConversation({ customer_id: 'CUST001', case_id: null, channel: 'chat', mode: 'human', opened_at: at });
    const evidence = await store.addEvidence({ conversation_id: conversation.id, case_id: null, type: 'image', path: '/files/demo/parcel_b_open.jpg', source: 'customer', created_at: at });
    const message = await store.addMessage({ conversation_id: conversation.id, role: 'customer', actor: 'CUST001', text: 'Please follow up', created_at: at });
    await store.linkConversation(conversation.id, 'CS001', 'CS_B', at);
    expect((await store.get('conversations', conversation.id))?.case_id).toBe('CS001');
    expect((await store.get('evidence', evidence.id))?.case_id).toBe('CS001');
    expect((await store.get('cases', 'CS001'))?.assignee).toBe('CS_B');
    expect(await store.get('messages', message.id)).toEqual(message);
    expect(await store.list('case_events', { type: 'assignee_changed' })).toHaveLength(1);
    const task = await store.createTask({ case_id: 'CS001', team: 'operations', status: 'open', evidence_ids: ['EV1', evidence.id], created_at: at });
    expect((await store.get('tasks', task.id))?.evidence_ids).toEqual(['EV1', evidence.id]);
  });
  it('serves real health and authenticated reset', async () => {
    const app = createApp(store, { token: [REDACTED], demo });
    expect(await (await app.request('/api/health')).json()).toMatchObject({ ok: true, db: 'up' });
    await demo.reset('After Demo 1');
    expect((await app.request('/api/demo/reset', { method: 'POST', headers: { 'x-demo-token': [REDACTED] } })).status).toBe(200);
    expect(await store.list('cases')).toEqual([]);
  });
  it('reads tool context and shipment changes after jump + advance through the app', async () => {
    const app = createApp(store, { token: [REDACTED], demo });
    const post = { method: 'POST', headers: { 'x-demo-token': [REDACTED] } };
    expect((await app.request('/api/demo/jump?to=demo2', post)).status).toBe(200);
    expect((await find_cases(store, { customer_id: 'CUST001', order_id: 'DH001' }))[0]).toMatchObject({ case_id: 'CS001', score: 0.9 });
    expect((await app.request('/api/demo/advance-day', post)).status).toBe(200);
    const context = await (await app.request('/api/cases/CS001/context')).json();
    expect(context.changes_since_last_contact).toEqual([{ parcel_code: 'B', before: 'in_transit', after: 'delivered' }]);
    const shipments = await (await app.request('/api/orders/DH001/shipments')).json();
    expect(shipments.parcels).toContainEqual(expect.objectContaining({ parcel_code: 'B', status: 'delivered', items: [expect.objectContaining({ id: 'ITEM2' })] }));
import { vi } from 'vitest';
import { type DatabaseState, type DbRows, type DbTable } from '@seapilot/contracts';
import type { CaseStore } from '../store/CaseStore';
import { DemoClock } from '../demo/clock';
import { buildSeed } from '../demo/seed';

// Test double only. Production always uses the injected PostgreSQL CaseStore.
export function testStore(initial = buildSeed('After Demo 1', new DemoClock())) {
  let state: DatabaseState = structuredClone(initial);
  const store: CaseStore = {
    health: async () => true,
    get: async <K extends DbTable>(table: K, id: string) => state[table].find(row => row.id === id) as DbRows[K] | undefined,
    list: async <K extends DbTable>(table: K, filter: Partial<DbRows[K]> = {}) =>
      (state[table] as DbRows[K][]).filter(row => Object.entries(filter).every(([key, value]) => row[key as keyof DbRows[K]] === value)),
    addEvent: vi.fn(async input => {
      const row = { ...input, id: input.id ?? `CE-test-${state.case_events.length}` };
      state.case_events.push(row);
      return row;
    }),
    resetTo: async next => { state = structuredClone(next); },
    updateShipment: async (id, patch) => {
      const row = state.shipments.find(item => item.id === id)!;
      Object.assign(row, patch);
      return row;
    },
    transaction: work => work(store),
    createConversation: vi.fn(), addMessage: vi.fn(), addEvidence: vi.fn(), createCase: vi.fn(),
    linkConversation: vi.fn(), createTask: vi.fn(), updateCase: vi.fn(),
  };
  return store;
}
